const image=(id,w=900)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const products=[{name:'The Everyday Polo',category:'Polos',price:1290,color:'Warm terracotta',image:'photo-1625910513413-5fc45e7dcb1e'},{name:'The Weekend Shirt',category:'Shirts',price:1490,color:'Natural white',image:'photo-1598033129183-c4f50c736f10'},{name:'The Relaxed Trouser',category:'Trousers',price:1890,color:'Stone',image:'photo-1473966968600-fa801b869a1a'},{name:'The Essential Oxford',category:'Shirts',price:1690,color:'Soft blue',image:'photo-1596755094514-f87e34085b2c'}];
const looks=[{image:'photo-1617137968427-85924c800a22',label:'THE EVERYDAY EDIT',bg:'#f8f5e6',product:0},{image:'photo-1591047139829-d91aecb6caea',label:'THE REFINED EDIT',bg:'#e6e9dd',product:3},{image:'photo-1516257984-b1b4d707412e',label:'THE UNWIND EDIT',bg:'#eee1d2',product:1}];let selectedLook=0;let cart=[];try{cart=JSON.parse(localStorage.getItem('shades-bag')||'[]').filter(x=>products[x.id]&&['S','M','L','XL'].includes(x.size)&&Number.isInteger(x.qty)&&x.qty>0)}catch{}const money=n=>'₹'+n.toLocaleString('en-IN');const productModal=document.querySelector('#product-modal'),cartModal=document.querySelector('#cart-modal');
function renderProducts(filter='All'){document.querySelector('#products').innerHTML=products.map((p,i)=>filter==='All'||p.category===filter?`<button class="product" data-product="${i}"><div class="product-image"><img loading="lazy" src="${image(p.image)}" alt="${p.name}, sample collection photography"><span aria-hidden="true">＋</span></div><h3>${p.name}</h3><div class="product-meta"><span>${p.color}</span><span>${money(p.price)}</span></div></button>`:'').join('');document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(+b.dataset.product))}renderProducts();
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderProducts(b.dataset.filter)});
document.querySelectorAll('[data-look]').forEach(b=>b.onclick=()=>{selectedLook=+b.dataset.look;const l=looks[selectedLook];document.querySelectorAll('[data-look]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelector('#hero-img').src=image(l.image,1400);document.querySelector('.hero-copy .eyebrow').textContent=l.label;document.querySelector('#hero').style.background=l.bg});
function openProduct(i){const p=products[i];document.querySelector('#product-detail').innerHTML=`<img src="${image(p.image)}" alt="${p.name}"><div><span class="eyebrow">THE PREVIEW COLLECTION</span><h2>${p.name}</h2><p>${p.color} · ${money(p.price)}</p><p>Easy to wear, easy to make your own. A considered addition to your everyday rotation.</p><label for="size">Choose your size</label><select id="size"><option value="">Select size</option><option>S</option><option>M</option><option>L</option><option>XL</option></select><button class="pill" id="add">Add to bag <span>＋</span></button><p class="demo-note">Sample product. Final fabric, sizing and availability to be confirmed.</p></div>`;productModal.showModal();document.querySelector('#add').onclick=()=>{const size=document.querySelector('#size').value;if(!size){document.querySelector('#size').focus();return}const existing=cart.find(x=>x.id===i&&x.size===size);if(existing)existing.qty++;else cart.push({id:i,size,qty:1});save();productModal.close();const t=document.querySelector('#toast');t.textContent='Added to your bag';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}}
function save(){try{localStorage.setItem('shades-bag',JSON.stringify(cart))}catch{}document.querySelector('#count').textContent=cart.reduce((s,x)=>s+x.qty,0)}save();
function renderCart(){document.querySelector('#cart-items').innerHTML=cart.length?cart.map((x,i)=>`<div class="cart-row"><img src="${image(products[x.id].image,200)}" alt="${products[x.id].name}"><div>${products[x.id].name}<p>Size ${x.size} · ${money(products[x.id].price)}</p><button aria-label="Decrease quantity" data-qty="${i}" data-change="-1">−</button>${x.qty}<button aria-label="Increase quantity" data-qty="${i}" data-change="1">＋</button></div><button aria-label="Remove ${products[x.id].name}" data-remove="${i}">×</button></div>`).join(''):'<p>Your bag is waiting for its first favourite.</p>';document.querySelector('#cart-total').textContent='Subtotal '+money(cart.reduce((s,x)=>s+products[x.id].price*x.qty,0));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(+b.dataset.remove,1);save();renderCart()});document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const i=+b.dataset.qty;cart[i].qty+=+b.dataset.change;if(cart[i].qty<1)cart.splice(i,1);save();renderCart()})}document.querySelector('#bag').onclick=()=>{renderCart();cartModal.showModal()};document.querySelector('.shop-look').onclick=()=>openProduct(looks[selectedLook].product);document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelector('#continue').onclick=()=>cartModal.close();document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.querySelector('#year').textContent=new Date().getFullYear();
